        public override void ReadWrite(CPlugVehicleMaterial n, GbxReaderWriter rw)
        {
            rw.VersionInt32(this);
            if (Version > 14)
            {
                throw new global::GBX.NET.Exceptions.ChunkVersionNotSupportedException(Version);
            }

            rw.Single(ref U01);
            rw.Single(ref U02);
            rw.Single(ref U03);
            rw.Single(ref U04);
            rw.Byte(ref U05);

            if (Version == 1)
            {
                rw.Single(ref U06);
                rw.Single(ref U07);
            }

            if (Version >= 7)
            {
                rw.Single(ref U08);
                rw.Single(ref U09);
            }

            if (Version >= 1)
            {
                rw.Single(ref U10);
                rw.Single(ref U11);
                rw.Single(ref U12);
            }

            if (Version >= 2)
            {
                rw.Single(ref U13);
            }

            if (Version >= 3)
            {
                rw.Single(ref U14);
                rw.Single(ref U15);
                rw.Single(ref U16);
            }

            if (Version >= 4)
            {
                rw.Boolean(ref U17);
                rw.Vec2(ref U18);
            }

            if (Version >= 5)
            {
                rw.Single(ref U19);
            }

            if (Version >= 6)
            {
                rw.Single(ref U20);
            }

            if (Version >= 8)
            {
                rw.Single(ref U21);

                if (Version <= 13)
                {
                    rw.Single(ref U22);
                }
            }

            if (Version >= 9)
            {
                rw.ReadableWritable<PlugCurve>(ref U23, version: Version- 12);
            }

            if (Version >= 10)
            {
                rw.ReadableWritable<PlugCurve>(ref U24, version: Version- 12);
            }

            if (Version >= 11)
            {
                rw.Single(ref U25);
            }

            if (Version >= 13)
            {
                rw.ReadableWritable<PlugCurve>(ref U26, version: Version- 12);
                rw.ReadableWritable<PlugCurve>(ref U27, version: Version- 12);
                rw.Single(ref U28);
                rw.Single(ref U29);
                rw.Single(ref U30);
            }

            if (Version >= 14)
            {
                rw.ReadableWritable<PlugCurve>(ref U31, version: Version- 12);
                rw.Int32(ref U32);
            }
        }
